sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmName ?director ?directorName ?deathDate
WHERE {
  VALUES ?film { dbr:The_People_vs._Larry_Flynt dbr:Manila_in_the_Claws_of_Light }

  # film label
  ?film rdfs:label ?filmName .
  FILTER (lang(?filmName) = "en")

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?dir1 . }
  OPTIONAL { ?film dbo:director ?dir2 . }
  BIND (COALESCE(?dir1, ?dir2) AS ?director)

  # director label
  ?director rdfs:label ?directorName .
  FILTER (lang(?directorName) = "en")

  # death date (prefer dbo:deathDate, fallback to dbp:deathDate)
  OPTIONAL { ?director dbo:deathDate ?death1 . }
  OPTIONAL { ?director dbp:deathDate ?death2 . }
  BIND (COALESCE(?death1, ?death2) AS ?deathDate)
}
LIMIT 100

